import{_ as e,o as a,c as d,a2 as l}from"./chunks/framework.D2UY-RsB.js";const h=JSON.parse('{"title":"Vito API Reference 📚","description":"","frontmatter":{},"headers":[],"relativePath":"en/api/overview.md","filePath":"en/api/overview.md"}'),o={name:"en/api/overview.md"};function s(i,t,r,c,n,p){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="vito-api-reference-📚" tabindex="-1">Vito API Reference 📚 <a class="header-anchor" href="#vito-api-reference-📚" aria-label="Permalink to &quot;Vito API Reference 📚&quot;">​</a></h1><p>Complete API reference for the core components of the <strong>Vito Web Framework</strong>.</p><hr><h2 id="🏗-vitoapp-class" tabindex="-1">🏗 <code>VitoApp</code> Class <a class="header-anchor" href="#🏗-vitoapp-class" aria-label="Permalink to &quot;🏗 `VitoApp` Class&quot;">​</a></h2><h3 id="createapp" tabindex="-1"><code>createApp()</code> <a class="header-anchor" href="#createapp" aria-label="Permalink to &quot;`createApp()`&quot;">​</a></h3><p>Initializes a new instance of the Vito application.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="app-get-path-handler-app-post-path-handler-app-put-app-delete" tabindex="-1"><code>app.get(path, handler)</code> / <code>app.post(path, handler)</code> / <code>app.put()</code> / <code>app.delete()</code> <a class="header-anchor" href="#app-get-path-handler-app-post-path-handler-app-put-app-delete" aria-label="Permalink to &quot;`app.get(path, handler)` / `app.post(path, handler)` / `app.put()` / `app.delete()`&quot;">​</a></h3><p>Registers a route handler for the specified HTTP verb.</p><h3 id="app-group-prefix-callback" tabindex="-1"><code>app.group(prefix, callback)</code> <a class="header-anchor" href="#app-group-prefix-callback" aria-label="Permalink to &quot;`app.group(prefix, callback)`&quot;">​</a></h3><p>Groups routes under a common path prefix.</p><h3 id="app-use-middleware" tabindex="-1"><code>app.use(middleware)</code> <a class="header-anchor" href="#app-use-middleware" aria-label="Permalink to &quot;`app.use(middleware)`&quot;">​</a></h3><p>Applies a middleware to the request processing pipeline.</p><h3 id="app-setstrictslash-strict-boolean" tabindex="-1"><code>app.setStrictSlash(strict: boolean)</code> <a class="header-anchor" href="#app-setstrictslash-strict-boolean" aria-label="Permalink to &quot;`app.setStrictSlash(strict: boolean)`&quot;">​</a></h3><p>Enables/disables Strict Trailing Slash Normalization (<code>/users/</code> vs <code>/users</code>). Default: <code>false</code> (Lax mode).</p><h3 id="app-setnotfoundhandler-handler" tabindex="-1"><code>app.setNotFoundHandler(handler)</code> <a class="header-anchor" href="#app-setnotfoundhandler-handler" aria-label="Permalink to &quot;`app.setNotFoundHandler(handler)`&quot;">​</a></h3><p>Sets a custom handler for 404 Not Found responses.</p><h3 id="app-listen-port" tabindex="-1"><code>app.listen(port)</code> <a class="header-anchor" href="#app-listen-port" aria-label="Permalink to &quot;`app.listen(port)`&quot;">​</a></h3><p>Starts listening for HTTP connections on the given port.</p><hr><h2 id="📊-observability-metrics-dx-phase-14" tabindex="-1">📊 Observability, Metrics &amp; DX (<code>Phase 14</code>) <a class="header-anchor" href="#📊-observability-metrics-dx-phase-14" aria-label="Permalink to &quot;📊 Observability, Metrics &amp; DX (`Phase 14`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createPrometheusRegistry()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Initializes Prometheus Metrics Registry collecting HTTP &amp; OS runtime stats.</td></tr><tr><td style="text-align:left;"><code>registry.recordRequest(method, path, status, duration)</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Records HTTP request metrics across latency quantiles (p50, p90, p99).</td></tr><tr><td style="text-align:left;"><code>registry.renderPrometheusMetrics()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Exports standard Prometheus exposition format text data.</td></tr><tr><td style="text-align:left;"><code>extractTraceParent(header)</code> / <code>injectTraceParent</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Extracts and injects OpenTelemetry (OTel) W3C <code>traceparent</code> headers.</td></tr><tr><td style="text-align:left;"><code>createMockHttpEngine()</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Initializes ultra-fast In-Memory HTTP Injector for Test Suites.</td></tr><tr><td style="text-align:left;"><code>mockEngine.inject(app, method, path, headers, body)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Simulates HTTP requests directly in memory without TCP sockets.</td></tr><tr><td style="text-align:left;"><code>createTestDbFixture(name)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Instantiates test fixture helper for seeding data.</td></tr><tr><td style="text-align:left;"><code>fixture.beginIsolationTransaction()</code> / <code>rollbackIsolationTransaction</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Automatically ROLLBACKS DB transactions post-test to maintain clean state.</td></tr><tr><td style="text-align:left;"><code>createVitCodeGenerator()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Generates boilerplate for Controllers, Services, Middlewares, Models, and Migrations.</td></tr><tr><td style="text-align:left;"><code>createVitDoctor()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Performs interactive system environment and resource diagnostics.</td></tr></tbody></table><hr><h2 id="🔒-auth-security-suite-packages-packages-auth" tabindex="-1">🔒 Auth &amp; Security Suite Packages (<code>packages/auth/</code>) <a class="header-anchor" href="#🔒-auth-security-suite-packages-packages-auth" aria-label="Permalink to &quot;🔒 Auth &amp; Security Suite Packages (`packages/auth/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>verifyJwtToken(token, secret, algo)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Verifies JWT Token signatures (<code>HS256</code>, <code>RS256</code>, <code>ES256</code>) in $&lt; 0.1\\text{ms}$.</td></tr><tr><td style="text-align:left;"><code>parseJwtToken(token)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Extracts Header and Payload Claims from raw JWT strings.</td></tr><tr><td style="text-align:left;"><code>validateJwtClaims(jwt, now, exp, nbf)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Validates token expiration (<code>exp</code>) and active time (<code>nbf</code>).</td></tr><tr><td style="text-align:left;"><code>jwtGuardMiddleware</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Automatically authenticates Bearer tokens and rejects unauthorized requests with HTTP 401.</td></tr><tr><td style="text-align:left;"><code>createGoogleOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initializes Google OAuth2 &amp; OIDC Client Helper with PKCE support.</td></tr><tr><td style="text-align:left;"><code>createGitHubOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initializes GitHub OAuth2 Provider Config.</td></tr><tr><td style="text-align:left;"><code>createMicrosoftOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Initializes Microsoft Azure AD / Entra ID OAuth2 Provider Config.</td></tr><tr><td style="text-align:left;"><code>config.generateAuthorizationUrl(state, challenge)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Generates OAuth2 redirect URL with PKCE challenge parameter.</td></tr><tr><td style="text-align:left;"><code>createApiKeyStore()</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">Instantiates API Key Store with per-client-key rate limiting quota management.</td></tr><tr><td style="text-align:left;"><code>hashApiKey(rawKey)</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">Single-way key hashing for secure database storage.</td></tr><tr><td style="text-align:left;"><code>hashPasswordArgon2id(pass, salt, params)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Hashes passwords with Argon2id matching OWASP recommendations.</td></tr><tr><td style="text-align:left;"><code>hashPasswordBcrypt(pass, salt, cost)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Hashes passwords with Bcrypt using configurable cost factors.</td></tr><tr><td style="text-align:left;"><code>encryptAES256GCM(plain, key, iv, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Two-way AEAD encryption formatted as <code>iv:ciphertext:tag</code>.</td></tr><tr><td style="text-align:left;"><code>decryptAES256GCM(payload, key, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Decrypts payloads and validates AES-256-GCM authentication tag.</td></tr><tr><td style="text-align:left;"><code>timingSafeEqual(strA, strB)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Constant-time string comparison preventing side-channel timing attacks.</td></tr><tr><td style="text-align:left;"><code>createRoleGuard(role, currentRoles)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Initializes RBAC Role Guard (rejecting unauthorized with HTTP 403).</td></tr><tr><td style="text-align:left;"><code>createPermissionGuard(perm, currentPerms)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Initializes RBAC Permission Guard for route action authorization.</td></tr><tr><td style="text-align:left;"><code>createGateEngine()</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Instantiates ABAC Policy Engine for resource context authorization.</td></tr></tbody></table><hr><h2 id="🗄️-database-orm-packages-packages-db-packages-orm" tabindex="-1">🗄️ Database &amp; ORM Packages (<code>packages/db</code> &amp; <code>packages/orm</code>) <a class="header-anchor" href="#🗄️-database-orm-packages-packages-db-packages-orm" aria-label="Permalink to &quot;🗄️ Database &amp; ORM Packages (`packages/db` &amp; `packages/orm`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createConnectionPool(type, connStr, min, max)</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Initializes auto-scaling Connection Pool with transparent health checks.</td></tr><tr><td style="text-align:left;"><code>pool.acquireConnection()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Borrows a valid database connection from Connection Pool.</td></tr><tr><td style="text-align:left;"><code>pool.checkHealthAndReconnect()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Performs connection health check &amp; transparent reconnect ($&lt; 100\\text{ms}$).</td></tr><tr><td style="text-align:left;"><code>beginTransaction(id)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Starts atomic database transaction enforcing ACID compliance.</td></tr><tr><td style="text-align:left;"><code>tx.createSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Creates savepoints for nested transactions.</td></tr><tr><td style="text-align:left;"><code>tx.rollbackToSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Rollbacks transaction state to specified savepoint.</td></tr><tr><td style="text-align:left;"><code>createMigrationRunner()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Instantiates Migration Runner executing Up/Down scripts tracked in <code>schema_migrations</code>.</td></tr><tr><td style="text-align:left;"><code>createSchemaDiffGenerator()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Generates SQL migration scripts automatically from Vito ORM Models.</td></tr><tr><td style="text-align:left;"><code>createDatabaseSeeder()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Creates Database Seeder helper for Dev &amp; Staging environments.</td></tr></tbody></table><hr><h2 id="⚡-performance-packages-packages-pool-packages-router" tabindex="-1">⚡ Performance Packages (<code>packages/pool</code> &amp; <code>packages/router</code>) <a class="header-anchor" href="#⚡-performance-packages-packages-pool-packages-router" aria-label="Permalink to &quot;⚡ Performance Packages (`packages/pool` &amp; `packages/router`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Helper</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createMemoryArena()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Creates reusable Request Memory Arena slots manager.</td></tr><tr><td style="text-align:left;"><code>createTcpBufferPool()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Creates Buffer Recycling Pool for TCP Read/Write buffers.</td></tr><tr><td style="text-align:left;"><code>zeroAllocHeaderLookup(raw, target)</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Extracts header value directly from raw HTTP stream without memory allocation.</td></tr><tr><td style="text-align:left;"><code>createRadixRouter(strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Initializes Radix Trie Router with $O(1)$ Static Route Fast Path.</td></tr><tr><td style="text-align:left;"><code>normalizePath(path, strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Normalizes URL paths according to Lax / Strict slash mode.</td></tr></tbody></table><hr><h2 id="📥-request-class" tabindex="-1">📥 <code>Request</code> Class <a class="header-anchor" href="#📥-request-class" aria-label="Permalink to &quot;📥 `Request` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>req.param(key)</code></td><td style="text-align:left;">Retrieves dynamic path parameter <code>:key</code> or <code>*wildcard</code></td><td style="text-align:left;"><code>req.param(&quot;id&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.query(key)</code></td><td style="text-align:left;">Retrieves search query parameter <code>?key=val</code></td><td style="text-align:left;"><code>req.query(&quot;page&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.header(key)</code></td><td style="text-align:left;">Retrieves HTTP request header value</td><td style="text-align:left;"><code>req.header(&quot;Authorization&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.method</code></td><td style="text-align:left;">Property returning HTTP method (GET, POST...)</td><td style="text-align:left;"><code>req.method</code></td></tr><tr><td style="text-align:left;"><code>req.path</code></td><td style="text-align:left;">Property returning URL path</td><td style="text-align:left;"><code>req.path</code></td></tr></tbody></table><hr><h2 id="📤-response-class" tabindex="-1">📤 <code>Response</code> Class <a class="header-anchor" href="#📤-response-class" aria-label="Permalink to &quot;📤 `Response` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>res.setStatus(code)</code></td><td style="text-align:left;">Sets HTTP Status Code (200, 404, 500...)</td><td style="text-align:left;"><code>res.setStatus(200)</code></td></tr><tr><td style="text-align:left;"><code>res.setHeader(name, val)</code></td><td style="text-align:left;">Sets HTTP Response Header</td><td style="text-align:left;"><code>res.setHeader(&quot;X-Powered-By&quot;, &quot;Vito&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.setCookie(key, val, opts)</code></td><td style="text-align:left;">Sets Cookie with HMAC signature &amp; HttpOnly/SameSite flags</td><td style="text-align:left;"><code>res.setCookie(&quot;sid&quot;, &quot;abc&quot;, opts)</code></td></tr><tr><td style="text-align:left;"><code>res.json(jsonStr)</code></td><td style="text-align:left;">Responds with JSON string and <code>Content-Type: application/json</code></td><td style="text-align:left;"><code>res.json(&quot;{\\&quot;ok\\&quot;:true}&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.html(htmlStr)</code></td><td style="text-align:left;">Responds with HTML content and <code>Content-Type: text/html</code></td><td style="text-align:left;"><code>res.html(&quot;&lt;h1&gt;Hi&lt;/h1&gt;&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.send(textStr)</code></td><td style="text-align:left;">Responds with Plain Text</td><td style="text-align:left;"><code>res.send(&quot;Hello World&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.sendChunk(chunk)</code></td><td style="text-align:left;">Sends chunked / streamed response data</td><td style="text-align:left;"><code>res.sendChunk(data)</code></td></tr></tbody></table><hr><h2 id="⚡-websockets-event-bus-job-queue-phase-13" tabindex="-1">⚡ WebSockets, Event Bus &amp; Job Queue (<code>Phase 13</code>) <a class="header-anchor" href="#⚡-websockets-event-bus-job-queue-phase-13" aria-label="Permalink to &quot;⚡ WebSockets, Event Bus &amp; Job Queue (`Phase 13`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Structure</th><th style="text-align:left;">Package</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createWebSocketServer(port, maxConn)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Initializes High-Concurrency WebSocket Server engine.</td></tr><tr><td style="text-align:left;"><code>wsServer.broadcastToRoom(room, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Broadcasts message to all connected clients in a Room.</td></tr><tr><td style="text-align:left;"><code>wsServer.unicast(client, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Sends a private message to a specific WebSocket Client.</td></tr><tr><td style="text-align:left;"><code>wsServer.checkHeartbeats(client, time)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Checks Ping/Pong and evicts dead connections (Stale eviction).</td></tr><tr><td style="text-align:left;"><code>compressFrame(payload)</code> / <code>decompressFrame</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Compresses and decompresses WebSocket frames via per-message deflate.</td></tr><tr><td style="text-align:left;"><code>createEventBus()</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Initializes Async Internal Event Bus dispatcher.</td></tr><tr><td style="text-align:left;"><code>eventBus.emitAsync(event, payload)</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Dispatches events asynchronously without blocking main loop.</td></tr><tr><td style="text-align:left;"><code>createRedisPubSubAdapter(host, port)</code></td><td style="text-align:left;"><code>packages/events/redis_pubsub.vit</code></td><td style="text-align:left;">Creates Redis Pub/Sub adapter for inter-node cluster communication.</td></tr><tr><td style="text-align:left;"><code>createJobQueue(driver)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Initializes Background Job Queue (Driver: <code>&quot;memory&quot;</code> or <code>&quot;redis&quot;</code>).</td></tr><tr><td style="text-align:left;"><code>jobQueue.scheduleJob(job, delayMs)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Pushes delayed job into schedule queue based on timer.</td></tr><tr><td style="text-align:left;"><code>jobQueue.processNextJob(shouldFail, reason)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Processes next job, handling Exponential Backoff Retries &amp; DLQ.</td></tr></tbody></table>',40)])])}const y=e(o,[["render",s]]);export{h as __pageData,y as default};
